<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Services\ProviderConfigurationService; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request;
class ProviderConfigurationController extends Controller { public function __construct(private readonly ProviderConfigurationService $service) {} public function index(): JsonResponse { return $this->successResponse($this->service->publicProfiles()); } public function update(Request $request): JsonResponse { $data=$request->validate(['profiles'=>['required','array','min:1'],'profiles.*.id'=>['nullable'],'profiles.*.name'=>['required','string','max:120'],'profiles.*.isActive'=>['required','boolean'],'profiles.*.values'=>['required','array']]); if(collect($data['profiles'])->where('isActive',true)->count()>1) return $this->errorResponse('Only one provider configuration may be active.',status:422); return $this->successResponse($this->service->replace($data['profiles']),'Provider configurations saved.'); } }
